};

const generateMockPayments = (): Payment[] => {
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth() + 1; // 1-12

  // Helper to format date
  const fmtDate = (d: number) => `${year}-${String(month).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

  return [
    { id: 'p1', platform: 'Uber Eats', amount: 240.50, date: fmtDate(5), status: 'received', estimated: false, domain: 'uber.com' },
    { id: 'p2', platform: 'Glovo', amount: 180.00, date: fmtDate(12), status: 'received', estimated: false, domain: 'glovoapp.com' },
    { id: 'p3', platform: 'Catcher', amount: 320.75, date: fmtDate(25), status: 'pending', estimated: true, domain: 'catcher.eu' },
    { id: 'p4', platform: 'Bolt Food', amount: 95.20, date: fmtDate(28), status: 'pending', estimated: true, domain: 'bolt.eu' },
    { id: 'p5', platform: 'Stuart', amount: 150.00, date: fmtDate(15), status: 'received', estimated: false, domain: 'stuart.com' },
    { id: 'p6', platform: 'Just Eat', amount: 210.00, date: fmtDate(19), status: 'pending', estimated: true, domain: 'just-eat.es' },
  ];
};

export const DataProvider: React.FC<PropsWithChildren<{}>> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [users, setUsers] = useState<User[]>([MOCK_USER, MOCK_MANAGER]);
  const [incomes, setIncomes] = useState<Income[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [payments, setPayments] = useState<Payment[]>([]);
  const [vehicle, setVehicle] = useState<Vehicle | null>(null);
  const [maintenanceRecords, setMaintenanceRecords] = useState<MaintenanceRecord[]>([]);
  const [hasOnboarded, setHasOnboarded] = useState(false);
  const [privacyMode, setPrivacyMode] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  // Load from localStorage on mount
  useEffect(() => {
    const loadData = () => {
      const storedIncomes = localStorage.getItem('labora_incomes');
      const storedExpenses = localStorage.getItem('labora_expenses');
      const storedDocs = localStorage.getItem('labora_docs');
      const storedOnboarding = localStorage.getItem('labora_onboarding');
      const storedPayments = localStorage.getItem('labora_payments');
      const storedPrivacy = localStorage.getItem('labora_privacy');
      const storedVehicle = localStorage.getItem('labora_vehicle');
      const storedMaintenance = localStorage.getItem('labora_maintenance');

      if (storedIncomes) setIncomes(JSON.parse(storedIncomes));
      if (storedExpenses) setExpenses(JSON.parse(storedExpenses));
      if (storedDocs) setDocuments(JSON.parse(storedDocs));
      if (storedOnboarding === 'true') setHasOnboarded(true);
      if (storedPrivacy === 'true') setPrivacyMode(true);
      if (storedMaintenance) setMaintenanceRecords(JSON.parse(storedMaintenance));

      if (storedVehicle) {
        setVehicle(JSON.parse(storedVehicle));
      } else {
        setVehicle(DEFAULT_VEHICLE);
      }

      if (storedPayments) {
        setPayments(JSON.parse(storedPayments));
      } else {
        setPayments(generateMockPayments());
      }
    };
    loadData();
  }, []);

  // Save to localStorage on change
  useEffect(() => {
    if (incomes.length > 0) localStorage.setItem('labora_incomes', JSON.stringify(incomes));
    if (expenses.length > 0) localStorage.setItem('labora_expenses', JSON.stringify(expenses));
    if (documents.length > 0) localStorage.setItem('labora_docs', JSON.stringify(documents));
    if (payments.length > 0) localStorage.setItem('labora_payments', JSON.stringify(payments));
    if (vehicle) localStorage.setItem('labora_vehicle', JSON.stringify(vehicle));
    if (maintenanceRecords.length > 0) localStorage.setItem('labora_maintenance', JSON.stringify(maintenanceRecords));
    localStorage.setItem('labora_onboarding', String(hasOnboarded));
    localStorage.setItem('labora_privacy', String(privacyMode));
  }, [incomes, expenses, documents, hasOnboarded, payments, privacyMode, vehicle, maintenanceRecords]);

  const showNotification = (type: 'success' | 'error' | 'info', message: string) => {
    const id = Math.random().toString(36).substr(2, 9);
    setNotifications(prev => [...prev, { id, type, message }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 3000);
  };

  const dismissNotification = (id: string) => {
    setNotifications(prev => prev.filter(n => n.id !== id));
  };

  const login = (email: string, role: UserRole) => {
    const found = users.find(u => u.email === email && u.role === role);
    if (found) {
      setCurrentUser(found);
      showNotification('success', `Bienvenido de nuevo, ${found.name}`);
    } else {
      const newUser: User = {
        id: Math.random().toString(36).substr(2, 9),
        name: email.split('@')[0],
        email,
        role,
        platforms: role === UserRole.RIDER ? ['Uber Eats'] : [],
        managerId: role === UserRole.RIDER ? 'm1' : undefined
      };
      setUsers(prev => [...prev, newUser]);
      setCurrentUser(newUser);
      showNotification('success', 'Cuenta creada correctamente');
    }
  };

  const logout = () => {
    setCurrentUser(null);
    showNotification('info', 'Sesión cerrada');
  };

  const completeOnboarding = () => {
    setHasOnboarded(true);
    showNotification('success', '¡Configuración completada!');
  };

  const togglePrivacyMode = () => {
    setPrivacyMode(prev => {
      const newVal = !prev;
      showNotification('info', newVal ? 'Modo Discreto Activado' : 'Modo Discreto Desactivado');
      return newVal;
    });
  };

  const addIncome = (inc: Omit<Income, 'id' | 'userId'>) => {
    if (!currentUser) return;
    const newIncome: Income = {
      ...inc,
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id
    };
    setIncomes(prev => [newIncome, ...prev]);
    showNotification('success', 'Ingreso registrado');
  };

  // NEW: Batch Add Incomes
  const addIncomes = (incs: Omit<Income, 'id' | 'userId'>[]) => {
    if (!currentUser) return;
    const newIncomes = incs.map(inc => ({
      ...inc,
      id: Math.random().toString(36).substr(2, 9) + Math.random().toString(36).substr(2, 5),
      userId: currentUser.id
    }));
    setIncomes(prev => [...newIncomes, ...prev]);
  };

  const addExpense = (exp: Omit<Expense, 'id' | 'userId'>) => {
    if (!currentUser) return;
    const newExpense: Expense = {
      ...exp,
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id
    };
    setExpenses(prev => [newExpense, ...prev]);
    showNotification('success', 'Gasto guardado y categorizado');
  };

  // NEW: Batch Add Expenses
  const addExpenses = (exps: Omit<Expense, 'id' | 'userId'>[]) => {
    if (!currentUser) return;
    const newExpenses = exps.map(exp => ({
      ...exp,
      id: Math.random().toString(36).substr(2, 9) + Math.random().toString(36).substr(2, 5),
      userId: currentUser.id
    }));
    setExpenses(prev => [...newExpenses, ...prev]);
  };

  const updateExpense = (updatedExpense: Expense) => {
    setExpenses(prev => prev.map(exp => exp.id === updatedExpense.id ? updatedExpense : exp));
    showNotification('success', 'Gasto actualizado');
  };

  const addDocument = (doc: Omit<Document, 'id' | 'userId'>) => {
    if (!currentUser) return;
    const newDoc: Document = {
      ...doc,
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id
    };
    setDocuments(prev => [newDoc, ...prev]);
    showNotification('success', 'Documento subido');
  };

  const updateVehicle = (vehicleData: Vehicle) => {
    setVehicle(vehicleData);
    showNotification('success', 'Datos del vehículo actualizados');
  };

  const addMaintenanceRecord = (record: Omit<MaintenanceRecord, 'id'>) => {
    const newRecord: MaintenanceRecord = {
      ...record,
      id: Math.random().toString(36).substr(2, 9)
    };
    setMaintenanceRecords(prev => [newRecord, ...prev]);

    // Auto-update vehicle stats
    if (vehicle) {
      const updatedVehicle: Vehicle = {
        ...vehicle,
        lastMaintenanceDate: record.date,
        lastMaintenanceKm: record.km,
        currentKm: Math.max(vehicle.currentKm, record.km),
        nextMaintenanceKm: record.nextPlannedKm || (record.km + 5000) // Default 5000km interval if not provided
      };
      setVehicle(updatedVehicle);
    }

    showNotification('success', 'Mantenimiento registrado');
  };

  const addPayment = (payment: Omit<Payment, 'id'>) => {
    const newPayment: Payment = {
      ...payment,
      id: Math.random().toString(36).substr(2, 9)
    };
    setPayments(prev => [...prev, newPayment]);
    showNotification('success', 'Pago previsto añadido');
  };

  const markPaymentAsReceived = (paymentId: string) => {
    setPayments(prev => prev.map(p => {
      if (p.id === paymentId) {
        if (p.status === 'pending' && currentUser) {
          const newIncome: Income = {
            id: Math.random().toString(36).substr(2, 9),
            userId: currentUser.id,
            platform: p.platform,
            amount: p.amount,
            date: new Date().toISOString().split('T')[0],
            retention: 0
          };
          setIncomes(current => [newIncome, ...current]);
        }
        return { ...p, status: 'received', estimated: false };
      }
      return p;
    }));
    showNotification('success', 'Pago marcado como recibido');
  };

  const exportData = () => {
    const data = { incomes, expenses, documents, vehicle, payments, maintenanceRecords };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `labora_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showNotification('success', 'Copia de seguridad descargada');
  };

  const importData = (jsonData: string) => {
    try {
      const data = JSON.parse(jsonData);
      if (data.incomes) setIncomes(data.incomes);
      if (data.expenses) setExpenses(data.expenses);
      if (data.documents) setDocuments(data.documents);
      if (data.vehicle) setVehicle(data.vehicle);
      if (data.payments) setPayments(data.payments);
      if (data.maintenanceRecords) setMaintenanceRecords(data.maintenanceRecords);
      showNotification('success', 'Datos restaurados correctamente');
    } catch (e) {
      showNotification('error', 'Archivo de copia de seguridad inválido');
    }
  };

  const getFiscalSummary = (userId: string): FiscalSummary => {
    const userIncomes = incomes.filter(i => i.userId === userId);
    const userExpenses = expenses.filter(e => e.userId === userId);

    const totalIncome = userIncomes.reduce((sum, i) => sum + i.amount, 0);
    const totalExpenses = userExpenses.reduce((sum, e) => sum + e.amount, 0);
    const netProfit = totalIncome - totalExpenses;

    // Simple 20% IRPF Estimation
    const estimatedIRPF = Math.max(0, netProfit * 0.20); 

    return {
      totalIncome,
      totalExpenses,
      netProfit,
      estimatedIRPF,
      quarter: 'Q1 2024'
    };
  };

  const getUsersByManager = (managerId: string): User[] => {
    return users.filter(u => u.managerId === managerId);
  };

  const value = {
    currentUser,
    users,
    incomes,
    expenses,
    documents,
    payments,
    vehicle,
    maintenanceRecords,
    hasOnboarded,
    privacyMode,
    notifications,
    togglePrivacyMode,
    completeOnboarding,
    login,
    logout,
    addIncome,
    addIncomes,
    addExpense,
    addExpenses,
    updateExpense,
    addDocument,
    addPayment,
    updateVehicle,
    addMaintenanceRecord,
    getFiscalSummary,
    getUsersByManager,
    markPaymentAsReceived,
    showNotification,
    dismissNotification,
    exportData,
    importData
  };

  return (
    <DataContext.Provider value={value}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (context === undefined) {
    throw new Error('useData must be used within a DataProvider');
  }
  return context;
};
