}

export interface BankInfo {
  name: string;
  logo: string; // URL or identifier
  type: 'traditional' | 'neobank';
}

export interface InstantPaymentOption {
  name: string;
  fee: string;
}

export interface PayoutMethod {
  method: string;
  time: string;
  fee: string;
}

export interface BankingMetadata {
  compatible_banks: BankInfo[];
  deposit_time_standard: string;
  deposit_time_instant: string;
  avg_transfer_fee: number;
