    bicycle: number;
    motorcycle: number;
    car: number;
  };
}

export interface PlatformDetails {
  id: string;
  name: string;
  color_hex: string; // Brand color
  base_fare: number;
  rate_km: number;
  rate_min: number;
  commission_pct: number;
  payment_speed: 'daily' | 'weekly' | 'biweekly'; // For sorting/badges
  incentives_summary: string; // e.g. "Multiplicador x1.2 Lluvia"
  logo_domain: string; // clearbit domain
}

export interface LaborAdvicePoint {
  title: string;
  description: string;
  severity: 'info' | 'warning' | 'critical';
}

export interface LaborAdvisorMetadata {
  tax_entity_name: string; // e.g. "Hacienda (AEAT)", "SAT"
