import Documents from './components/Documents';
import FiscalChat from './components/FiscalChat';
import Login from './components/Login';
import Simulator from './components/Simulator';
import Education from './components/Education';
import ManagerDashboard from './components/ManagerDashboard';
import Profile from './components/Profile';
import Onboarding from './components/Onboarding';
import Settings from './components/Settings';
import Calendar from './components/Calendar';
import Logo from './components/Logo';
import Toast from './components/Toast';
import IntroAnimation from './components/IntroAnimation';
import { ComparatorView } from './modules/platform-comparator/components/ComparatorView'; 
import { LaborAdvisorView } from './modules/labor-advisor/components/LaborAdvisorView';
import { EventsView } from './modules/events/components/EventsView';
import { RouteOptimizer } from './modules/routes/components/RouteOptimizer';
import { PayoutFastCheck } from './modules/payouts/components/PayoutFastCheck';
import { RiskMonitor } from './modules/risks/components/RiskMonitor';
import { InternationalTaxCalc } from './modules/taxes/components/InternationalTaxCalc';
import { ProDashboard } from './modules/kpis/components/ProDashboard';
import { RiderToolkit } from './modules/toolkit/components/RiderToolkit';
import { CityLivingCost } from './modules/city-costs/components/CityLivingCost';

import { LayoutDashboard, Activity, MessageSquare, FileText, User, Calendar as CalendarIcon, Menu, Award } from 'lucide-react';

const MainLayout: React.FC = () => {
  const { currentUser, hasOnboarded, completeOnboarding } = useData();
  const [currentView, setView] = useState('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Redirect manager to their dashboard by default
  React.useEffect(() => {
    if (currentUser?.role === 'MANAGER' && currentView === 'dashboard') {
      setView('manager-dashboard');
    }
  }, [currentUser, currentView]);

  if (!currentUser) return <Login />;

  // Show onboarding only for Riders who haven't finished it
  if (currentUser.role === 'RIDER' && !hasOnboarded) {
    return <Onboarding onFinish={completeOnboarding} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <Dashboard setView={setView} />;
      case 'movements': return <Movements />;
      case 'calendar': return <Calendar />;
      case 'documents': return <Documents />;
      case 'chat': 
      case 'ai': return <FiscalChat />;
      case 'simulator': return <Simulator />;
      case 'education': return <Education setView={setView} />;
      case 'profile': return <Profile />;
      case 'settings': return <Settings />;
      case 'comparator': return <ComparatorView />;
      case 'advisor': return <LaborAdvisorView />; 

      // New Modules
      case 'events': return <EventsView />;
      case 'routes': return <RouteOptimizer />;
      case 'payouts': return <PayoutFastCheck />;
      case 'risks': return <RiskMonitor />;
      case 'taxes': return <InternationalTaxCalc />;
      case 'kpis': return <ProDashboard />;
      case 'toolkit': return <RiderToolkit />;
      case 'city': return <CityLivingCost />;

      // Manager
      case 'manager-dashboard': return <ManagerDashboard />;
      case 'chat-internal': return <div className="p-8 text-center text-gray-500">Chat interno en construcción</div>;

      default: return <Dashboard setView={setView} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Inicio', icon: LayoutDashboard },
    { id: 'movements', label: 'Movs', icon: Activity },
    { id: 'comparator', label: 'Pro', icon: Award },
    { id: 'ai', label: 'IA', icon: MessageSquare },
    { id: 'profile', label: 'Perfil', icon: User },
  ];

  return (
    <div className="flex min-h-screen bg-[#F3F4F6] font-sans text-[#1A1A1A]">
      <Toast />
      {/* Desktop Sidebar */}
      <Sidebar 
        currentView={currentView} 
        setView={setView} 
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Mobile Header (Only visible on mobile) */}
        <header className="lg:hidden bg-white/80 backdrop-blur-md border-b border-gray-200 p-4 flex items-center justify-between z-10 sticky top-0">
          <Logo size="sm" />
          <button 
            onClick={() => setIsMobileMenuOpen(true)}
            className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <Menu size={24} />
          </button>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth">
          <div className="max-w-7xl mx-auto">
            {renderView()}
          </div>
        </div>

        {/* Mobile Bottom Nav */}
        <nav className="lg:hidden bg-white border-t border-gray-200 px-6 py-3 flex justify-between items-center z-20 safe-area-bottom">
          {navItems.map((item) => (
            <button
