import React, { createContext, useContext, useState, useEffect, PropsWithChildren } from 'react';
import { CountryConfig, DEFAULT_SPAIN_CONFIG, DEFAULT_MEXICO_CONFIG, DEFAULT_USA_CONFIG } from '../modules/country-config/types';

interface CountryContextType {
  selectedCountry: CountryConfig;
  setCountry: (code: string) => void;
  availableCountries: CountryConfig[];
}

const CountryContext = createContext<CountryContextType | undefined>(undefined);

export const CountryProvider: React.FC<PropsWithChildren<{}>> = ({ children }) => {
  const [selectedCountry, setSelectedCountry] = useState<CountryConfig>(DEFAULT_SPAIN_CONFIG);

  const availableCountries = [DEFAULT_SPAIN_CONFIG, DEFAULT_MEXICO_CONFIG, DEFAULT_USA_CONFIG];

  const setCountry = (code: string) => {
    const found = availableCountries.find(c => c.country_code === code);
    if (found) setSelectedCountry(found);
  };

  return (
    <CountryContext.Provider value={{ selectedCountry, setCountry, availableCountries }}>
      {children}
    </CountryContext.Provider>
  );
};

export const useCountry = () => {
  const context = useContext(CountryContext);
  if (!context) throw new Error("useCountry must be used within a CountryProvider");
  return context;
};

