interface IntroAnimationProps {
  onComplete: () => void;
}

const IntroAnimation: React.FC<IntroAnimationProps> = ({ onComplete }) => {
  const [stage, setStage] = useState(0); // 0: Init, 1: Logo Reveal, 2: Text, 3: FadeOut

  useEffect(() => {
    // Cinematic Sequence
    const t1 = setTimeout(() => setStage(1), 500);
    const t2 = setTimeout(() => setStage(2), 1200);
    const t3 = setTimeout(() => setStage(3), 3500);
    const t4 = setTimeout(onComplete, 4200);

    return () => {
      clearTimeout(t1); clearTimeout(t2); clearTimeout(t3); clearTimeout(t4);
    };
  }, [onComplete]);

  return (
    <div className={`fixed inset-0 z-[100] bg-white flex flex-col items-center justify-center transition-opacity duration-700 ${stage === 3 ? 'opacity-0' : 'opacity-100'}`}>

      {/* Background Particles (CSS only simulation for simplicity) */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className={`absolute top-1/4 left-1/4 w-64 h-64 bg-blue-100 rounded-full blur-[80px] opacity-50 transition-transform duration-[3s] ${stage > 0 ? 'scale-150' : 'scale-50'}`}></div>
        <div className={`absolute bottom-1/4 right-1/4 w-64 h-64 bg-green-100 rounded-full blur-[80px] opacity-50 transition-transform duration-[3s] ${stage > 0 ? 'scale-125' : 'scale-50'}`}></div>
      </div>

      <div className="relative z-10 flex flex-col items-center">
         <div className={`transition-all duration-1000 transform ${stage >= 1 ? 'opacity-100 translate-y-0 scale-100' : 'opacity-0 translate-y-10 scale-90'}`}>
            <Logo size="xl" showText={false} animated={true} />
         </div>

         <div className={`mt-6 text-center transition-all duration-1000 delay-300 transform ${stage >= 2 ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-5'}`}>
            <h1 className="text-4xl md:text-5xl font-bold text-gray-900 tracking-tight">
              Labora<span className="text-[#34A853] inline-block animate-pulse">+</span>
            </h1>
            <p className="mt-2 text-gray-500 text-lg font-light tracking-wide">Tu asistente fiscal inteligente</p>
         </div>
      </div>
    </div>
  );
};

