import React, { useState } from 'react';
import { useCountry } from '../contexts/CountryContext';
import { Calculator, AlertCircle, Globe } from 'lucide-react';

const Simulator: React.FC = () => {
  const { selectedCountry } = useCountry();
  const [income, setIncome] = useState(2000);
  const [expense, setExpense] = useState(500);

  const profit = income - expense;

  // Calculate dynamic tax based on country brackets
  const calculateTax = (amount: number) => {
    if (amount <= 0) return 0;
    const bracket = selectedCountry.income_tax_brackets.find(b => amount >= b.min && amount < b.max);
    const rate = bracket ? bracket.rate : 0.20;
    return amount * rate;
  };

  const estimatedTax = calculateTax(profit);
  const net = profit - estimatedTax;

  return (
    <div className="max-w-3xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 pb-24 lg:pb-0">

      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 flex items-center gap-2">
            <Calculator className="text-[#4285F4]" />
            Simulador
          </h2>
          <div className="flex items-center gap-2 mt-1">
             <Globe size={14} className="text-gray-400" />
             <p className="text-gray-500">Reglas fiscales: <span className="font-bold text-gray-800">{selectedCountry.display_name}</span></p>
          </div>
        </div>
      </div>

      <div className="bg-white p-8 rounded-[28px] shadow-sm space-y-8">
        <div>
          <div className="flex justify-between mb-2">
             <label className="text-sm font-bold text-gray-700">Ingresos Mensuales Estimados</label>
             <span className="text-lg font-bold text-[#4285F4]">{income} {selectedCountry.currency_symbol}</span>
          </div>
          <input 
            type="range" min="0" max="10000" step="100"
            value={income} onChange={(e) => setIncome(Number(e.target.value))}
            className="w-full h-2 bg-blue-100 rounded-lg appearance-none cursor-pointer"
          />
        </div>

        <div>
          <div className="flex justify-between mb-2">
             <label className="text-sm font-bold text-gray-700">Gastos Deducibles (Gasolina, Equipo)</label>
             <span className="text-lg font-bold text-[#EA4335]">{expense} {selectedCountry.currency_symbol}</span>
          </div>
          <input 
            type="range" min="0" max="5000" step="50"
            value={expense} onChange={(e) => setExpense(Number(e.target.value))}
            className="w-full h-2 bg-red-100 rounded-lg appearance-none cursor-pointer"
          />
        </div>

        <div className="border-t border-gray-100 pt-8 grid grid-cols-1 md:grid-cols-3 gap-6 text-center">
          <div className="p-4 rounded-2xl bg-gray-50">
             <p className="text-xs text-gray-500 uppercase font-bold mb-2">Beneficio Bruto</p>
             <p className="text-3xl font-bold text-gray-900">{profit.toFixed(0)} <span className="text-base">{selectedCountry.currency_symbol}</span></p>
          </div>
          <div className="p-4 rounded-2xl bg-blue-50">
             <p className="text-xs text-blue-500 uppercase font-bold mb-2">Impuestos Est.</p>
             <p className="text-3xl font-bold text-blue-600">{estimatedTax.toFixed(0)} <span className="text-base">{selectedCountry.currency_symbol}</span></p>
          </div>
          <div className="p-4 rounded-2xl bg-green-50 shadow-sm border border-green-100">
             <p className="text-xs text-green-600 uppercase font-bold mb-2">Neto Real</p>
             <p className="text-4xl font-black text-green-700">{net.toFixed(0)} <span className="text-base">{selectedCountry.currency_symbol}</span></p>
          </div>
        </div>
      </div>

      <div className="bg-yellow-50 border border-yellow-100 p-4 rounded-2xl flex gap-3">
        <AlertCircle className="text-yellow-600 flex-shrink-0" />
        <div>
          <h4 className="font-bold text-yellow-800 text-sm">Nota Legal ({selectedCountry.country_code})</h4>
          <p className="text-sm text-yellow-700 mt-1 leading-relaxed">
            {selectedCountry.legal_notes}
          </p>
        </div>
      </div>
    </div>
  );
};
