import Toast from './components/Toast';
import IntroAnimation from './components/IntroAnimation';
import { LayoutDashboard, Activity, MessageSquare, FileText, User, Calendar as CalendarIcon, Menu } from 'lucide-react';

const MainLayout: React.FC = () => {
  const { currentUser, hasOnboarded, completeOnboarding } = useData();
  const [currentView, setView] = useState('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Redirect manager to their dashboard by default
  React.useEffect(() => {
    if (currentUser?.role === 'MANAGER' && currentView === 'dashboard') {
      setView('manager-dashboard');
    }
  }, [currentUser, currentView]);

  if (!currentUser) return <Login />;

  if (currentUser.role === 'RIDER' && !hasOnboarded) {
    return <Onboarding onFinish={completeOnboarding} />;
  }

  const renderView = () => {
    switch (currentView) {
      case 'dashboard': return <Dashboard setView={setView} />;
      case 'movements': return <Movements />;
      case 'calendar': return <Calendar />;
      case 'documents': return <Documents />;
      case 'chat': 
      case 'ai': return <FiscalChat />;
      case 'simulator': return <Simulator />;
      case 'education': return <Education setView={setView} />;
      case 'profile': return <Profile />;
      case 'settings': return <Settings />;
      case 'manager-dashboard': return <ManagerDashboard />;
      case 'chat-internal': return <div className="p-8 text-center text-gray-500">Chat interno en construcción</div>;
      default: return <Dashboard setView={setView} />;
    }
  };

  const navItems = [
    { id: 'dashboard', label: 'Inicio', icon: LayoutDashboard },
    { id: 'movements', label: 'Movs', icon: Activity },
    { id: 'ai', label: 'IA', icon: MessageSquare },
    { id: 'profile', label: 'Perfil', icon: User },
  ];

  return (
    <div className="flex min-h-screen bg-[#F8F9FA] font-sans text-[#1F1F1F]">
      <Toast />
      <Sidebar 
        currentView={currentView} 
        setView={setView} 
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="lg:hidden bg-white border-b border-gray-200 p-4 flex items-center justify-between z-10 sticky top-0">
          <Logo size="sm" />
          <button 
            onClick={() => setIsMobileMenuOpen(true)}
            className="p-2 text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
          >
            <Menu size={24} />
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-8 scroll-smooth">
          <div className="max-w-7xl mx-auto">
            {renderView()}
          </div>
        </div>

        <nav className="lg:hidden bg-white border-t border-gray-200 px-6 py-3 flex justify-between items-center z-20 safe-area-bottom">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setView(item.id)}
              className={`flex flex-col items-center gap-1 transition-colors ${
                currentView === item.id ? 'text-[#4285F4]' : 'text-gray-400 hover:text-gray-600'
              }`}
            >
              <item.icon size={24} strokeWidth={currentView === item.id ? 2.5 : 2} />
              <span className="text-[10px] font-medium">{item.label}</span>
            </button>
          ))}
        </nav>
      </main>
    </div>
  );
};

const App: React.FC = () => {
  const [showIntro, setShowIntro] = useState(true);

  return (
    <CountryProvider>
      <DataProvider>
        {showIntro ? (
          <IntroAnimation onComplete={() => setShowIntro(false)} />
        ) : (
          <MainLayout />
        )}
