import React, { createContext, useContext, useState, useEffect, PropsWithChildren } from 'react';
import { CountryConfig, DEFAULT_SPAIN_CONFIG, DEFAULT_MEXICO_CONFIG, DEFAULT_USA_CONFIG } from '../modules/country-config/types';

interface CountryContextType {
  selectedCountry: CountryConfig;
  selectCountry: (code: string) => void;
  countries: CountryConfig[];
  refreshCountries: () => Promise<void>;
}

export const CountryContext = createContext<CountryContextType | undefined>(undefined);

export const CountryProvider: React.FC<PropsWithChildren<{}>> = ({ children }) => {
  const [selectedCountry, setSelectedCountry] = useState<CountryConfig>(DEFAULT_SPAIN_CONFIG);

  const countries = [DEFAULT_SPAIN_CONFIG, DEFAULT_MEXICO_CONFIG, DEFAULT_USA_CONFIG];

  const selectCountry = (code: string) => {
    const found = countries.find(c => c.country_code === code);
    if (found) setSelectedCountry(found);
  };

  const refreshCountries = async () => {
    // In a real app, this would fetch updated configs from an API.
    // For now, we rely on the static defaults.
    return Promise.resolve();
  };

  return (
    <CountryContext.Provider value={{ selectedCountry, selectCountry, countries, refreshCountries }}>
      {children}
    </CountryContext.Provider>
  );
};

export const useCountry = () => {
  const context = useContext(CountryContext);
  if (!context) throw new Error("useCountry must be used within a CountryProvider");
  return context;
};

import { useContext } from 'react';
import { CountryContext } from '../../../contexts/CountryContext';
import { DEFAULT_SPAIN_CONFIG, CountryConfig } from '../types';

/**
 * Hook para que los módulos existentes (Simulator, Dashboard, etc.)
 * obtengan la configuración del país actual.
 * 
 * Implementa patrón de "Graceful Degradation":
 * Si la feature flag está apagada, devuelve hardcoded España.
 */
export const useCountryConfig = (): CountryConfig => {
  const context = useContext(CountryContext);

  // Check feature flag (mocked for now, assumes enabled if code is present)
  // En producción real: const enabled = useFeatureFlag('country_expand_v1');
  const featureEnabled = true; 

  if (!featureEnabled || !context) {
    return DEFAULT_SPAIN_CONFIG;
  }

  return context.selectedCountry;
};

