         </div>

      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { useCountry } from '../contexts/CountryContext';
import { Globe, ChevronDown, Search, X } from 'lucide-react';

interface CountrySelectorProps {
  variant?: 'dropdown' | 'cards';
}

const CountrySelector: React.FC<CountrySelectorProps> = ({ variant = 'dropdown' }) => {
  const { selectedCountry, selectCountry, countries } = useCountry();
  const [filterQuery, setFilterQuery] = useState('');

  const filteredCountries = useMemo(() => {
    const query = filterQuery.toLowerCase().trim();
    if (!query) return countries;
    return countries.filter(c => 
      c.country_code.toLowerCase().includes(query) || 
      c.display_name.toLowerCase().includes(query)
    );
  }, [countries, filterQuery]);

  const getFlag = (code: string) => {
    switch (code) {
      case 'ES': return '🇪🇸';
      case 'MX': return '🇲🇽';
      case 'US': return '🇺🇸';
      default: return '🌍';
    }
  };

  if (variant === 'cards') {
    return (
      <div className="space-y-4 w-full">
        {/* Search Bar for Cards View */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
          <input 
            type="text"
            placeholder="Buscar por código (ES, MX...)"
            value={filterQuery}
            onChange={(e) => setFilterQuery(e.target.value)}
            className="w-full pl-10 pr-10 py-2.5 bg-gray-50 border border-gray-200 rounded-xl text-sm focus:ring-2 focus:ring-[#4285F4] focus:bg-white outline-none transition-all"
          />
          {filterQuery && (
            <button 
              onClick={() => setFilterQuery('')}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
            >
              <X size={14} />
            </button>
          )}
        </div>

        <div className="grid grid-cols-3 gap-2">
          {filteredCountries.map(c => (
            <button
              key={c.country_code}
              onClick={() => selectCountry(c.country_code)}
              className={`p-3 rounded-xl border text-center transition-all animate-in fade-in zoom-in-95 duration-200 ${
                selectedCountry.country_code === c.country_code 
                  ? 'border-[#4285F4] bg-blue-50 text-[#4285F4] font-bold shadow-sm' 
                  : 'border-gray-200 bg-white hover:bg-gray-50'
              }`}
            >
              <span className="text-2xl block mb-1">{getFlag(c.country_code)}</span>
              <span className="text-xs">{c.country_code}</span>
            </button>
          ))}
          {filteredCountries.length === 0 && (
            <div className="col-span-3 py-4 text-center text-xs text-gray-400 italic">
              No se encontraron países
            </div>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="relative group">
      <button className="flex items-center gap-2 bg-gray-50 hover:bg-gray-100 px-3 py-2 rounded-full transition-colors">
        <span className="text-lg">{getFlag(selectedCountry.country_code)}</span>
        <span className="text-sm font-bold text-gray-700">{selectedCountry.country_code}</span>
        <ChevronDown size={14} className="text-gray-400" />
      </button>

      <div className="absolute top-full right-0 mt-2 w-56 bg-white rounded-2xl shadow-2xl border border-gray-100 overflow-hidden hidden group-hover:block z-50 animate-in fade-in zoom-in-95 duration-200">
        {/* Mini Search inside Dropdown */}
        <div className="p-2 border-b border-gray-50 bg-gray-50/50">
          <div className="relative">
            <Search className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-400" size={12} />
            <input 
              type="text"
              placeholder="Filtrar..."
              value={filterQuery}
              onChange={(e) => setFilterQuery(e.target.value)}
              className="w-full pl-7 pr-2 py-1.5 bg-white border border-gray-200 rounded-lg text-xs outline-none focus:border-[#4285F4]"
              onClick={(e) => e.stopPropagation()}
            />
          </div>
        </div>

        <div className="max-h-60 overflow-y-auto py-1">
          {filteredCountries.map(c => (
            <button
              key={c.country_code}
              onClick={() => {
                selectCountry(c.country_code);
                setFilterQuery('');
              }}
              className={`w-full text-left px-4 py-2.5 hover:bg-gray-50 flex items-center justify-between text-sm font-medium ${
                selectedCountry.country_code === c.country_code ? 'text-[#4285F4] bg-blue-50/50' : 'text-gray-700'
              }`}
            >
              <div className="flex items-center gap-3">
                <span className="text-lg">{getFlag(c.country_code)}</span>
                <span>{c.display_name}</span>
              </div>
              <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-1.5 py-0.5 rounded uppercase">
                {c.country_code}
              </span>
            </button>
          ))}
          {filteredCountries.length === 0 && (
            <div className="px-4 py-3 text-xs text-gray-400 italic text-center">
              Sin resultados
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CountrySelector;

import React, { useState } from 'react';

interface TooltipSliderProps {
  min: number;
  max: number;
  step: number;
  value: number;
  onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  suffix?: string;
  className?: string;
}

const TooltipSlider: React.FC<TooltipSliderProps> = ({ 
  min, 
  max, 
  step, 
  value, 
  onChange, 
  suffix = "", 
  className = "" 
}) => {
  const [showTooltip, setShowTooltip] = useState(false);

  // Calcular la posición porcentual para el tooltip
  const percentage = ((value - min) / (max - min)) * 100;

  return (
    <div className="relative pt-6 pb-2 w-full">
      {/* Tooltip flotante */}
      <div 
        className={`absolute -top-1 transform -translate-x-1/2 mb-2 px-2 py-1 bg-gray-800 text-white text-[10px] font-bold rounded shadow-lg transition-opacity duration-200 pointer-events-none z-20 ${
          showTooltip ? 'opacity-100' : 'opacity-0'
        }`}
        style={{ left: `${percentage}%` }}
      >
        {value}{suffix}
        {/* Flecha del tooltip */}
        <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-2 h-2 bg-gray-800 rotate-45"></div>
      </div>

      <input 
        type="range" 
        min={min} 
        max={max} 
        step={step}
        value={value} 
        onChange={onChange}
        onMouseEnter={() => setShowTooltip(true)}
        onMouseLeave={() => setShowTooltip(false)}
        onMouseDown={() => setShowTooltip(true)}
        onMouseUp={() => setShowTooltip(false)}
        onTouchStart={() => setShowTooltip(true)}
        onTouchEnd={() => setShowTooltip(false)}
        className={`w-full h-2 rounded-lg appearance-none cursor-pointer accent-[#1A73E8] ${className}`}
      />
    </div>
  );
};

export default TooltipSlider;

import React, { useState, useMemo } from 'react';
import { useCountry } from '../contexts/CountryContext';
import { Calculator, AlertCircle, Globe, Clock, Wallet, Briefcase, TrendingDown, Building2, Check, ArrowRight, Map } from 'lucide-react';
import { TripCalculator } from './TripCalculator';
import TooltipSlider from './TooltipSlider';

const Simulator: React.FC = () => {
  const { selectedCountry } = useCountry();
  const [activeTab, setActiveTab] = useState<'monthly' | 'trip'>('monthly');

  // State for Monthly Simulator
  const [hoursPerWeek, setHoursPerWeek] = useState(30);
  const [hourlyGross, setHourlyGross] = useState(15); // Average gross earnings per hour
  const [expenses, setExpenses] = useState(200);
  const [selectedPlatformIds, setSelectedPlatformIds] = useState<string[]>([]);

  // Toggle platform selection
  const togglePlatform = (id: string) => {
    setSelectedPlatformIds(prev => 
      prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]
    );
  };

  // Calculations for Monthly
  const stats = useMemo(() => {
    // 1. Time & Gross
    const monthlyHours = hoursPerWeek * 4;
    const grossIncome = monthlyHours * hourlyGross;

    // 2. Platform Commissions
    let avgCommissionRate = selectedCountry.default_commission_pct;

    if (selectedPlatformIds.length > 0 && selectedCountry.platforms) {
      const selectedDetails = selectedCountry.platforms.filter(p => selectedPlatformIds.includes(p.id));
      if (selectedDetails.length > 0) {
        const totalRate = selectedDetails.reduce((acc, curr) => acc + curr.commission_pct, 0);
        avgCommissionRate = totalRate / selectedDetails.length;
      }
    }

    const platformFees = grossIncome * avgCommissionRate;

    // 3. Taxable Base
    const operatingProfit = grossIncome - platformFees - expenses;

    // 4. Taxes
    const calculateTax = (amount: number) => {
      if (amount <= 0) return 0;
      const projectedAnnual = amount * 12;
      const bracket = selectedCountry.income_tax_brackets.find(b => projectedAnnual >= b.min && projectedAnnual < b.max);
      const rate = bracket ? bracket.rate : (selectedCountry.income_tax_brackets[selectedCountry.income_tax_brackets.length-1]?.rate || 0.20);
      return amount * rate;
    };

    const estimatedTax = calculateTax(operatingProfit);

    // 5. Net
    const netIncome = operatingProfit - estimatedTax;

    return {
      monthlyHours,
      grossIncome,
      avgCommissionRate,
      platformFees,
      operatingProfit,
      estimatedTax,
      netIncome
    };
  }, [hoursPerWeek, hourlyGross, expenses, selectedPlatformIds, selectedCountry]);

  const formatMoney = (amount: number) => {
    return amount.toLocaleString('es-ES', { style: 'currency', currency: selectedCountry.currency, maximumFractionDigits: 0 });
  };

  return (
    <div className="max-w-5xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 pb-24 lg:pb-0">

      {/* Header & Tabs */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 flex items-center gap-2">
            <Calculator className="text-[#4285F4]" />
            Simulador de Ingresos
          </h2>
          <div className="flex items-center gap-2 mt-1">
             <Globe size={14} className="text-gray-400" />
             <p className="text-gray-500">Reglas fiscales: <span className="font-bold text-gray-800">{selectedCountry.display_name}</span></p>
          </div>
        </div>

        {/* Tab Switcher */}
        <div className="bg-white p-1 rounded-xl border border-gray-200 flex shadow-sm">
           <button 
             onClick={() => setActiveTab('monthly')}
             className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'monthly' ? 'bg-[#1A1A1A] text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
           >
             <Clock size={16} /> Proyección Mensual
           </button>
           <button 
             onClick={() => setActiveTab('trip')}
             className={`px-4 py-2 rounded-lg text-sm font-bold transition-all flex items-center gap-2 ${activeTab === 'trip' ? 'bg-[#1A1A1A] text-white shadow-md' : 'text-gray-500 hover:bg-gray-50'}`}
           >
             <Map size={16} /> Calculadora por Viaje
           </button>
        </div>
      </div>

      {activeTab === 'trip' ? (
        <TripCalculator />
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in slide-in-from-left-4 duration-300">

          {/* Left Column: Inputs */}
          <div className="lg:col-span-2 space-y-6">

            {/* Workload Card */}
            <div className="bg-white p-6 rounded-[24px] shadow-sm border border-gray-100">
              <h3 className="font-bold text-gray-800 mb-6 flex items-center gap-2">
                <Clock size={18} className="text-gray-400" /> Configuración Laboral
              </h3>

              <div className="space-y-6">
                <div>
                  <div className="flex justify-between mb-2">
                     <label className="text-sm font-bold text-gray-600">Horas Semanales</label>
                     <span className="text-lg font-bold text-[#4285F4]">{hoursPerWeek} h</span>
                  </div>
                  <TooltipSlider 
                    min={5} max={80} step={1}
                    value={hoursPerWeek} 
                    onChange={(e) => setHoursPerWeek(Number(e.target.value))}
                    suffix="h"
                    className="bg-blue-100"
                  />
                  <div className="flex justify-between text-xs text-gray-400 mt-1">
                    <span>Part-time</span>
                    <span>Full-time</span>
                    <span>Hardcore</span>
                  </div>
                </div>

                <div>
                  <div className="flex justify-between mb-2">
                     <label className="text-sm font-bold text-gray-600">Ingreso Bruto Promedio / Hora</label>
                     <span className="text-lg font-bold text-[#4285F4]">{hourlyGross} {selectedCountry.currency_symbol}</span>
                  </div>
                  <TooltipSlider 
                    min={5} max={50} step={0.5}
                    value={hourlyGross} 
                    onChange={(e) => setHourlyGross(Number(e.target.value))}
                    suffix={selectedCountry.currency_symbol}
                    className="bg-blue-100"
                  />
                </div>

                <div>
                  <div className="flex justify-between mb-2">
                     <label className="text-sm font-bold text-gray-600">Gastos Mensuales (Gasolina, Datos...)</label>
                     <span className="text-lg font-bold text-red-500">-{expenses} {selectedCountry.currency_symbol}</span>
                  </div>
                  <TooltipSlider 
                    min={0} max={1000} step={10}
                    value={expenses} 
                    onChange={(e) => setExpenses(Number(e.target.value))}
                    suffix={selectedCountry.currency_symbol}
                    className="bg-red-100"
                  />
                </div>
              </div>
            </div>

            {/* Platforms Selector */}
            <div className="bg-white p-6 rounded-[24px] shadow-sm border border-gray-100">
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-bold text-gray-800 flex items-center gap-2">
                  <Briefcase size={18} className="text-gray-400" /> Plataformas Activas
                </h3>
                {selectedPlatformIds.length > 0 && (
                  <span className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded-full font-medium">
                    Comisión Media: {(stats.avgCommissionRate * 100).toFixed(1)}%
                  </span>
                )}
              </div>

              <div className="flex flex-wrap gap-3">
                {selectedCountry.platforms?.map(p => {
                  const isSelected = selectedPlatformIds.includes(p.id);
                  return (
                    <button
                      key={p.id}
                      onClick={() => togglePlatform(p.id)}
                      className={`flex items-center gap-2 px-4 py-3 rounded-xl border transition-all ${
                        isSelected 
                          ? 'border-[#2D6CDF] bg-blue-50 text-[#2D6CDF] shadow-sm' 
                          : 'border-gray-200 bg-white text-gray-500 hover:border-gray-300'
                      }`}
                    >
                      {isSelected ? <Check size={16} /> : <div className="w-4" />}
                      <span className="font-bold text-sm">{p.name}</span>
                      <span className="text-xs opacity-70 ml-1">{(p.commission_pct * 100).toFixed(0)}%</span>
                    </button>
                  );
                })}
                {(!selectedCountry.platforms || selectedCountry.platforms.length === 0) && (
                  <p className="text-sm text-gray-400 italic">No hay plataformas específicas configuradas para este país.</p>
                )}
              </div>
            </div>

          </div>

          {/* Right Column: Results */}
          <div className="space-y-6">

            {/* Main Result Card */}
            <div className="bg-[#1A1A1A] text-white p-6 rounded-[28px] shadow-xl relative overflow-hidden">
               <div className="relative z-10">
